        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Data Quality Completeness', 'Validates all required market data, reference data, and trade data is present across the entity. Flags gaps in instrument codes, missing curve pillars, stale fixings, and orphaned trades. Runs early so downstream analytics have a clean data baseline.', 'risk', '0 5 * * 1-5', 'skip', 5, 'common', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Audit Trail Summary', 'Daily summary of all create, update, and delete operations across all domain entities for the entity. Broken down by service, actor, and change reason category. Supports SOX and SOC 2 compliance requirements for change logging.', 'risk', '0 6 * * 1-5', 'skip', 15, 'common', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'SA-CCR Exposure', 'Standardised Approach for Counterparty Credit Risk: computes Exposure-at-Default (EAD), Replacement Cost (RC), and Potential Future Exposure (PFE) per netting set under Basel III/IV supervisory rules. Required for Risk-Weighted Asset (RWA) and leverage ratio calculations. Replaces the legacy Current Exposure Method (CEM).', 'risk', '0 6 * * 1-5', 'skip', 20, 'regulatory', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Leverage Ratio', 'Computes the Basel III leverage ratio: Tier 1 capital divided by total exposure measure (on- and off-balance sheet, derivatives, SFTs). Alerts if the ratio approaches the 3% minimum threshold. Required for all regulated entities under CRR/Basel III pillar 2.', 'risk', '0 6 * * 1-5', 'skip', 25, 'regulatory', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'FRTB SA Capital', 'Fundamental Review of the Trading Book — Standardised Approach: computes market risk capital using supervisory-prescribed sensitivity-based method (SBM) across delta, vega, and curvature risk for all risk classes (GIRR, CSR, FX, EQ, CMDTY). Floor model and fallback for desks not approved for IMA.', 'risk', '0 7 * * 1-5', 'skip', 30, 'regulatory', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Liquidity Coverage', 'Liquidity Coverage Ratio (LCR): High-Quality Liquid Assets divided by net cash outflows over a 30-day stress horizon. Flags when HQLA buffer drops below 100% minimum. Required under Basel III for all regulated deposit-taking and investment firms.', 'risk', '0 7 * * 1-5', 'skip', 35, 'regulatory', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Large Exposures', 'Monitors single-counterparty exposure concentration against the 25% of Tier 1 capital regulatory limit. Aggregates across all netting sets, SFTs, and indirect exposures for each legal entity counterparty. Produces breach alerts and a top-20 concentration report.', 'risk', '0 7 * * 1-5', 'skip', 40, 'regulatory', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'CFTC Swap Data Reporting', 'Swap transaction reporting under CFTC Part 43/45 rules. Produces real-time public and regulatory reports for all swap transactions to a registered Swap Data Repository (SDR). Covers all CFTC-jurisdiction swaps. US entities only.', 'risk', '0 8 * * 1-5', 'skip', 50, 'regulatory', 'US'),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Model Calibration', 'Calibrates interest rate, FX, and volatility models (LGM, Hull-White, SABR, Black-Scholes) to live market data. Outputs calibrated parameters and fit quality metrics (RMSE). Must run before exposure simulation, XVA, and sensitivity analytics that depend on calibrated model parameters.', 'risk', '0 5 * * 1-5', 'skip', 80, 'trading', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Yield Curves', 'Bootstraps discount and projection yield curves from market instruments (deposits, FRAs, swaps, OIS, bonds). Outputs the full term structure of interest rates used by all pricing engines. Essential prerequisite for NPV, sensitivity, and Monte Carlo exposure analytics.', 'risk', '0 5 * * 1-5', 'skip', 85, 'trading', null),
