        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Credit Curves', 'Bootstraps CDS-implied survival probability curves and hazard rate curves for each counterparty and entity. Calibrates credit models (Jarrow-Turnbull, Hull-White credit) to market spreads. Prerequisite for CVA, DVA, FVA, and regulatory SA-CVA capital computations.', 'risk', '0 5 * * 1-5', 'skip', 100, 'trading', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'NPV', 'Full mark-to-market portfolio valuation producing present values for all active trades. Applies validated yield curves and FX rates. Provides the daily P&L baseline, feeds downstream sensitivities, and serves as the reference for risk-neutral pricing across all asset classes.', 'risk', '0 6 * * 1-5', 'skip', 105, 'trading', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Cashflows', 'Projects all future contractual cashflows across the portfolio: fixed, floating, contingent, and collateral flows. Used for liquidity risk, funding cost estimation, hedge effectiveness testing, and IFRS 9 / IFRS 7 cashflow disclosure.', 'risk', '0 6 * * 1-5', 'skip', 110, 'trading', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Delta and Gamma', 'Computes first-order (delta) and second-order (gamma) price sensitivities to interest rates, FX, and credit spreads using bump-and-revalue. Produces risk ladder reports by tenor bucket and currency. Feeds hedging, P&L attribution, and FRTB sensitivity-based method capital.', 'risk', '0 7 * * 1-5', 'skip', 115, 'trading', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Bucketed DV01', 'Key-rate DV01 (dollar value of one basis point) decomposition across standardised tenor buckets (1M, 3M, 6M, 1Y, 2Y, 5Y, 10Y, 20Y, 30Y). Provides a granular interest rate risk profile per currency, netting set, and book. Core input to duration management and FRTB delta capital.', 'risk', '0 7 * * 1-5', 'skip', 125, 'trading', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Exposure', 'Monte Carlo simulation of future exposure profiles (EE, PFE, EPE, ENE) at the netting-set level using risk-factor simulation. Drives CVA/DVA valuation, regulatory capital under SA-CCR, and internal credit limits. Computationally intensive; uses queue concurrency to serialise with other long-running reports.', 'risk', '0 8 * * 1-5', 'queue', 130, 'trading', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'CVA/DVA/FVA', 'Composite report computing all three valuation adjustments: Credit VA (counterparty default risk), Debit VA (own default risk), and Funding VA (uncollateralised funding cost). Uses exposure profiles from the Exposure report and credit curves from Credit Curves. Essential for IFRS 13 fair value.', 'risk', '0 8 * * 1-5', 'queue', 135, 'trading', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Stressed VaR', 'VaR computed over a stressed historical window (2008 financial crisis or COVID-2020) at 99% confidence, 10-day holding period. Required as a capital add-on under Basel 2.5 IMA. Uses full revaluation for non-linear exposures.', 'risk', '0 8 * * 1-5', 'skip', 140, 'trading', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'P&L Attribution', 'Daily decomposition of P&L into risk-factor components: delta, gamma, vega, theta, carry, and unexplained residual. Required for FRTB IMA back-testing and P&L attribution test (PLAT) compliance. Compares hypothetical P&L against actual P&L to validate model quality.', 'risk', '0 16 * * 1-5', 'skip', 145, 'trading', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 1, 'Intraday Risk Monitor', 'Real-time risk snapshot updated every 30 minutes during trading hours. Displays key risk metrics: PV, delta ladder, top 10 P&L movers, VaR estimate, and limit-utilisation gauges. Uses queue concurrency to serialise updates. Provides traders and desk heads with continuous risk visibility between end-of-day analytic runs.', 'risk', '*/30 8-17 * * 1-5', 'queue', 150, 'trading', null),
